Here's a complete example. I'll use a hypothetical REST API (e.g., a "Todo" API) to demonstrate the patterns.

---

### 1. Tool Class — `TodoApiTools.cs`

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;

[McpServerToolType]
public class TodoApiTools(HttpClient httpClient, ILogger<TodoApiTools> logger)
{
    [McpServerTool, Description("Get a todo item by its ID.")]
    public async Task<string> GetTodo(
        [Description("The numeric ID of the todo item")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching todo {Id}", id);
        var todo = await httpClient.GetFromJsonAsync<Todo>(
            $"/todos/{id}", cancellationToken);
        return $"[{(todo!.Completed ? "✓" : " ")}] {todo.Title}";
    }

    [McpServerTool, Description("List all todos, optionally filtered by completion status.")]
    public async Task<string> ListTodos(
        [Description("Filter: true=completed, false=pending, omit=all")] bool? completed = null,
        CancellationToken cancellationToken = default)
    {
        var url = completed.HasValue
            ? $"/todos?completed={completed.Value}"
            : "/todos";

        var todos = await httpClient.GetFromJsonAsync<List<Todo>>(url, cancellationToken);
        return string.Join("\n", todos!.Select(t => $"#{t.Id} [{(t.Completed ? "✓" : " ")}] {t.Title}"));
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new todo item and return its ID.")]
    public async Task<string> CreateTodo(
        [Description("Title of the new todo item")] string title,
        CancellationToken cancellationToken = default)
    {
        var response = await httpClient.PostAsJsonAsync("/todos",
            new { title, completed = false }, cancellationToken);
        response.EnsureSuccessStatusCode();
        var created = await response.Content.ReadFromJsonAsync<Todo>(cancellationToken);
        return $"Created todo #{created!.Id}: {created.Title}";
    }
}

public record Todo(int Id, string Title, bool Completed);
```

### 2. Program.cs — stdio transport

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: route all logging to stderr so stdout stays clean for JSON-RPC
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient with a base address for the API
builder.Services.AddHttpClient<TodoApiTools>(client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

builder.Services.AddMcpServer(options =>
{
    options.ServerInfo = new() { Name = "TodoMcpServer", Version = "1.0.0" };
    options.ServerInstructions = "Use these tools to manage todo items.";
})
.WithStdioServerTransport()
.WithToolsFromAssembly();

await builder.Build().RunAsync();
```

---

### How DI Works for MCP Tools

The SDK supports **two injection styles**:

| Style | Class type | How services arrive |
|---|---|---|
| **Constructor injection** | Non-static class | Services in the constructor (shown above — `HttpClient`, `ILogger<T>`) |
| **Method parameter injection** | Static class | Services as method params alongside user-facing params |

**Key rule:** The SDK distinguishes user-facing parameters from injected ones automatically. Types like `HttpClient`, `ILogger<T>`, `CancellationToken`, `IMcpServer`, and any DI-registered service are **resolved from the container** and **never appear in the tool's JSON schema** sent to the LLM. Only parameters with `[Description]` are exposed to the model.

In the example above, `TodoApiTools` uses **constructor injection** via a primary constructor. The `AddHttpClient<TodoApiTools>(...)` call registers a typed `HttpClient` that the SDK injects when it instantiates the tool class per request.

**Quick DI checklist:**
- `HttpClient` → `AddHttpClient<T>()` or `AddHttpClient()`
- `ILogger<T>` → registered automatically by the host
- Custom services → `builder.Services.AddSingleton<IMyService, MyService>()`
- `CancellationToken` → always injected, just add the parameter
